INSERT INTO `tbl_literasi_soal` VALUES('3','3','Literasi bukan sekadar kemampuan membaca dan menulis. Lebih dari itu, literasi adalah kunci membuka jendela dunia, sebuah kemampuan untuk memahami, menganalisis, mengkritisi, dan menggunakan informasi guna memecahkan masalah dalam kehidupan sehari-hari. Menjadi literat berarti memiliki kekuatan untuk terus bertumbuh, berpikir merdeka, dan berkontribusi secara positif bagi masyarakat.','EQWEQWE','WEQWE','QWEQWE','WEQWE','A','1');
