INSERT INTO `tbl_literasi_tugas` VALUES('3','1','199408052022212011','X E 1','LITERASI 1','Literasi bukan sekadar kemampuan membaca dan menulis. Lebih dari itu, literasi adalah kunci membuka jendela dunia, sebuah kemampuan untuk memahami, menganalisis, mengkritisi, dan menggunakan informasi guna memecahkan masalah dalam kehidupan sehari-hari. Menjadi literat berarti memiliki kekuatan untuk terus bertumbuh, berpikir merdeka, dan berkontribusi secara positif bagi masyarakat.','video','https://youtu.be/_Jl3r-XrqTw?si=gtvUTcAqmXA56KkH','180',NULL,'2026-06-18 14:11:08');
